import{c as t,Q as s,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const a="/assets/docs-screens-list.BhI9NS-6.png",r="/assets/docs-screens-create-dialog.C8t_mdfu.png",i="/assets/docs-screens-add-classes.D6lXhmXl.png",h="/assets/screen-settings-live-top10-stacked.DnxdEIzI.png",l="/assets/screen-live-top10-stacked.BPpqhRM8.png",d="/assets/screen-time-behind-superman.Ba5OWCMw.png",c="/assets/screen-position-bump.BPIoyomW.png",g="/assets/screen-settings-cycle-all-classes.CAoNzPG8.png",p="/assets/docs-screens-settings-start-times.C_ZTTbZz.png",u="/assets/docs-screens-start-times-tv.BlTocOYr.png",w="/assets/screen-settings-pinned-places.BXoNxRUb.png",m="/assets/leaderboard-pinned-places.Cuu6A7bT.png",f="/assets/screen-settings-snapshot-turned.rLrhldrb.png",y="/assets/docs-screens-fps-history.DKW4NIXi.png",q=JSON.parse('{"title":"Creating screens","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/creating-screens.md","filePath":"user/screens/creating-screens.md"}'),b={name:"user/screens/creating-screens.md"};function v(k,e,T,S,A,C){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="creating-screens" tabindex="-1">Creating screens <a class="header-anchor" href="#creating-screens" aria-label="Permalink to &quot;Creating screens&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators setting up spectator-facing displays.</p><p>A <strong>screen</strong> is a display you configure once and then open as a web page on a TV, laptop or tablet. Each screen has its own <strong>ID</strong>, its own layout, and — the first thing you choose — its own <strong>content</strong>: what it actually shows. Because a screen is just a web page, nothing is installed on the display device: you point its browser at the screen&#39;s URL and leave it running. See <a href="./../what-is-mesho-manager/">How meshO Manager works</a> for the one-server, many-browsers model.</p><p>A screen can show:</p><ul><li><strong>Leaderboard</strong> — live results, class by class. This is what every screen shows unless you change it. (The same board is the <strong>Leaderboard</strong> page inside Manager — see <a href="./leaderboard">Leaderboard</a>.)</li><li><strong>Start times</strong> — the start list, grouped under class or course headings.</li><li><strong>Live top 10</strong> — a wall of live top-10 boards, one per class. The same graph the spectator and kiosk screens draw, on a TV.</li><li><strong>Time behind Superman</strong> — a wall of Time behind Superman graphs, one per class, ten runners each. The finisher graph: it draws the races that are already in, so it is the screen for the half-hour after a class comes home.</li><li><strong>Position bump</strong> — the same wall drawing each runner&#39;s place overall after every leg, so you can see who was gaining and who was slipping back.</li></ul><p>So a hall with ten TVs might run the Leaderboard on seven of them, start times by the start lane, a Live top 10 wall over the finish, a Time behind Superman wall by the download desk, and a different set of classes on each of the rest. You choose per screen, in Manager — a TV has no controls on it and nobody needs to touch the display itself.</p><blockquote><p><strong>Note:</strong> These are the arena displays you build here. They&#39;re separate from the built-in <strong>Spectator</strong> and <strong>Kiosk</strong> views — the public, self-serve pages competitors open on their own phones — which need no setup (see <a href="./spectator-site-and-kiosk">Spectator site and kiosk</a>), and from the <a href="./info-screens">info screens</a> — the start clock, starters and radio-control feed you set up on the device itself. See the <a href="./../getting-started/concepts-glossary#screens-and-views">glossary</a> for the distinction.</p></blockquote><h2 id="the-screens-page" tabindex="-1">The Screens page <a class="header-anchor" href="#the-screens-page" aria-label="Permalink to &quot;The Screens page&quot;">​</a></h2><p>Open <strong>Screens</strong> from the event menu (under <strong>Race</strong>, then <strong>Admin</strong>). It has three sections:</p><ul><li><p><strong>Screens</strong> — every screen in the event, one row each, with what it shows and how it&#39;s doing.</p></li><li><p><strong>Commentary</strong> — <strong>Open</strong> starts the announcer&#39;s live feed in a new tab, and the table under it lists every commentary view that is open and when it was last heard from. See <a href="./commentary">Commentary</a>.</p></li><li><p><strong>Video</strong> — the arena cameras streaming now and the recordings kept on this server, with <strong>Play</strong> and <strong>Delete</strong> for each recording. Cameras are started on the device holding them, from the <a href="./info-screens#video">info screens</a>.</p><p>The Video heading says how much this event&#39;s recordings take up and how much disk is free, and <strong>Kept in</strong> names the folder they are in. <strong>Cameras streaming now</strong> lists each camera with its <strong>Control</strong>, <strong>Picture</strong>, how many screens are <strong>Watching</strong>, whether it is <strong>Recording</strong>, how much has been <strong>Received</strong> and when it <strong>Started</strong>. <strong>Recordings</strong> lists each one with its <strong>Length</strong> and <strong>Size</strong> (<strong>Not finished</strong> while a camera is still writing it), and <strong>Delete all recordings</strong> clears the lot. Recordings are not in the event backup, so a deleted one cannot be restored — see <a href="./info-screens#what-is-recorded-and-what-is-not">What is recorded, and what is not</a>.</p></li></ul><p><img src="'+a+'" alt="The Screens page with six screens. Across the top, Edit all Leaderboards, Leaderboard classes and New. Each row shows the Screen ID, what it Shows, its classes, Last heard from, and a reload and a gear button. all and manager show an &quot;All classes&quot; chip; manager has a dash for Last heard from and no reload button; start is a Start times screen showing &quot;Class · All classes&quot;; tv1 is expanded to its M21E and W21E chips; tv2 was last heard from 17 minutes ago in grey; wall is a Time behind Superman screen with four classes. The Commentary section below has an Open button."></p><p>Every event has two built-in screens. <strong>all</strong> shows every class and is the simplest thing to put on a single display. <strong>manager</strong> is the Leaderboard page inside Manager itself — it&#39;s listed here so you can set its layout, but it has no display device behind it, so its <strong>Last heard from</strong> cell shows a dash and it has no reload button. Its settings leave out <strong>Shows</strong>, <strong>Theme</strong>, <strong>Language</strong>, the snapshot and <strong>Delete</strong>: it is always a Leaderboard, and it follows your own language.</p><p>Click the <strong>Screen ID</strong> heading to sort the table by ID, and again to reverse it. Each ID is a link that opens that screen in a new browser tab. A row&#39;s <strong>Classes</strong> cell says how many classes the screen has (expand it with the arrow to see them as chips), <strong>Class · All classes</strong> or similar for a start times screen, and <strong>All classes</strong> for <strong>all</strong>, <strong>manager</strong> and a wall that cycles through every class. A wall carrying more classes than it can draw says <strong>First 12 only</strong> or <strong>First 4 only</strong>.</p><p>For a bank of TVs set up and managed together, see <a href="./tv-screens">TV screens</a>.</p><h2 id="creating-a-screen" tabindex="-1">Creating a screen <a class="header-anchor" href="#creating-a-screen" aria-label="Permalink to &quot;Creating a screen&quot;">​</a></h2><p>Click <strong>New</strong> beside the <strong>Screens</strong> heading. In <strong>Create new screen</strong>, give it a <strong>Screen ID</strong>, choose what it <strong>Shows</strong> and its <strong>Theme</strong>, and click <strong>Create</strong>. The ID is how you refer to the screen and it appears in the screen&#39;s URL, so keep it short and memorable (<code>elite</code>, <code>juniors</code>, <code>arena1</code>). It must be unique within the event — the dialog says <strong>Screen ID already exists</strong> if it isn&#39;t.</p><p><img src="'+r+'" alt="The Create new screen dialog: a Screen ID field, Shows set to Leaderboard and Theme set to Light, with Cancel and Create."></p><p><strong>Shows</strong> and <strong>Theme</strong> are asked here, rather than left to the gear icon afterwards, so a screen created for the start lane isn&#39;t a Leaderboard for however long it takes you to open its settings. Both default to what most screens are: <strong><a href="./leaderboard">Leaderboard</a></strong>, and <strong>Light</strong>.</p><p>A new screen inherits your <strong>Leaderboard screen defaults</strong> (set on the <a href="./../reference/settings">Settings</a> page) for club display, club icons, auto-scroll, the header, max radios, time display, single-line relay members and max places. Font size and columns are <em>not</em> among them — every new screen starts at 10 and 2 — and you can fine-tune any of it afterwards. A new Leaderboard starts with <strong>no classes</strong>, so the next step is to choose them.</p><p>There&#39;s another way to make a screen, and it&#39;s often quicker: point a browser at a screen URL that doesn&#39;t exist yet. A TV opened at <code>/screen/tv9</code> creates <code>tv9</code> and it appears on this page ready to be told what to show. A screen made that way does not take your Leaderboard screen defaults: it starts at font size 14, with club <strong>Abbreviations</strong> and the other settings at their built-in defaults, so check its settings once it appears.</p><h2 id="choosing-what-a-screen-shows" tabindex="-1">Choosing what a screen shows <a class="header-anchor" href="#choosing-what-a-screen-shows" aria-label="Permalink to &quot;Choosing what a screen shows&quot;">​</a></h2><p>Click the <strong>gear</strong> icon in a screen&#39;s row and set <strong>Shows</strong> to <strong><a href="./leaderboard">Leaderboard</a></strong>, <strong>Start times</strong>, <strong>Live top 10</strong>, <strong>Time behind Superman</strong> or <strong>Position bump</strong>. The rest of the settings follow that choice, so you only ever see the ones that apply.</p><h3 id="a-leaderboard-screen-which-classes" tabindex="-1">A Leaderboard screen: which classes <a class="header-anchor" href="#a-leaderboard-screen-which-classes" aria-label="Permalink to &quot;A Leaderboard screen: which classes&quot;">​</a></h3><p>There are two places to do this, and they do the same thing.</p><p><strong>In the screen&#39;s row</strong>, the <strong>Classes</strong> column:</p><ul><li><p>Click the <strong>expand</strong> arrow to see the classes currently on the screen as chips.</p></li><li><p>Click the <strong>+</strong> (add) button to open the <strong>Add classes</strong> dialog — search by class name (the <strong>Already on screens</strong> column shows which other screens already show each class), tick the ones you want, and click <strong>Add</strong> (it counts them: <strong>Add 3 classes</strong>). On a wall the dialog says how many more the screen takes. The search box has a <strong>Case sensitive search</strong> option, and <strong>Select all</strong> / <strong>Clear all</strong> at the foot of the dialog tick or untick every class in the list.</p><p><img src="'+i+'" alt="The Add classes dialog for tv1: a search box, a Case sensitive search tick box, and a table of the classes not yet on this screen — M20, W20 and Open — each with an &quot;Already on screens&quot; chip reading tv2. Select all, Clear all, Cancel and Add class across the foot."></p></li><li><p>Remove a class by clicking the <strong>×</strong> on its chip.</p></li><li><p>You can <strong>drag class chips between screens</strong> in the table to move them around quickly.</p></li></ul><p><strong>In the screen&#39;s settings</strong>, under <strong>Classes</strong>: the classes laid out <strong>the way the screen will lay them out</strong> — the same number of columns, filled in the same order. Drag one into a cell to move it there, <strong>×</strong> to remove, <strong>Add classes</strong> beside the heading to add more. Changes here are saved with <strong>Apply</strong> or <strong>Save</strong> like everything else in the dialog, so you can back out with <strong>Cancel</strong> — unlike the table row, where removing a chip takes effect straight away.</p><p>On a Leaderboard the grid follows the <strong>Columns</strong> setting, so changing it re-shapes the preview and you can see where each class will land. It shows which column a class is in and where in it; it can&#39;t show height, because a real column is as tall as the fields in it.</p><p>The <strong>all</strong> screen is special — it always shows <strong>All classes</strong> and you don&#39;t manage its class list. Nor does <strong>manager</strong>, which shows every class too.</p><h3 id="a-live-top-10-screen-which-classes" tabindex="-1">A Live top 10 screen: which classes <a class="header-anchor" href="#a-live-top-10-screen-which-classes" aria-label="Permalink to &quot;A Live top 10 screen: which classes&quot;">​</a></h3><p>Assign classes exactly as you would to a Leaderboard — either the <strong>Classes</strong> column in the screen&#39;s row, or the <strong>Classes</strong> section in the screen&#39;s settings.</p><p>In the settings, the class grid works as it does for a Leaderboard, except that a wall chooses its own shape rather than following a Columns setting — so it re-shapes as you add and remove, because the wall does. A wall&#39;s grid is exact: each cell is one board, and it follows <strong>Class layout</strong> below.</p><p><img src="'+h+'" alt="Screen settings for a Live top 10 screen: Shows Live top 10, Theme, Rotation and Language; under Classes, M21 Elite, W21 Elite, M20 and W20 stacked one per row with drag handles and an × each, and Add classes beside the heading; then Font size Large and Class layout Stacked."></p><p>A wall holds <strong>12 classes</strong>, and the settings will not let you go past it: <strong>Add classes</strong> stops offering once you are at twelve, and the picker says how many the screen takes. Remove one to make room.</p><p>A screen can still end up with more than twelve — assigned from the table row, which has no limit, or set up by an older version. The television draws the first twelve in your order and the screen&#39;s row says <strong>First 12 only</strong>; the extras stay on the screen and are managed from that row.</p><p>Each board is the same Live top 10 graph a spectator sees: one lane per runner, ten deep, including everyone still out in the forest. It sizes itself — how much each board says shrinks as you add classes — so there is no column setting on this screen, and nothing scrolls. What you get is what fits.</p><p><strong>Font size</strong> is <strong>Large</strong>, <strong>Medium</strong>, <strong>Small</strong> or <strong>Extra small</strong>, and shrinks the whole wall — text, lanes and all — rather than just the words. Large is how the wall has always looked, and is right for a TV read from across the arena. On a big screen or one people stand close to, a smaller size makes everything look less oversized, and it also gives every board more room: a board that had to drop the club or cut its field short at Large may show all of it at Small.</p><p><strong>Class layout</strong> is <strong>Side by side</strong> or <strong>Stacked</strong>. Side by side is how the wall has always looked: up to six boards across, then two rows. Stacked puts the boards one above the next — four classes are four full-width rows — and goes to a second column past four.</p><p>A board as wide as most of the screen — stacked boards while they fit in one column (up to four classes), or one class on its own — draws each runner on a single line: the name on the left, the track across the middle, the time on the right, with the class name beside the row of control codes rather than above it. That is what lets a short, wide board still show most of its class: on a 1080p TV, four stacked classes show about seven runners each at <strong>Large</strong>, and all ten at <strong>Small</strong>. When a board still cannot fit ten, it drops the leg times and clubs first, then shows the leaders and says so (&quot;Top 7 of 16&quot;).</p><p><img src="'+l+'" alt="A Live top 10 wall on a TV, stacked: four full-width boards for M21 Elite, W21 Elite, M20 and W20, each runner on one line with the name on the left, the track across the middle with a node at each radio control (105, 112, 118) and the finish, and the time on the right — a projected time with a ~ for a runner still out. Each board&#39;s corner says &quot;Top 4 of 16&quot; or &quot;Top 4 of 12&quot; and how many are on course."></p><p>A class the graph cannot draw — a relay, a score course, one with no course — says so on its own tile rather than being left out, so you can see that you assigned it.</p><p>The wall&#39;s header names the graph, <strong>Live top 10</strong>, rather than the event: somebody crossing the arena is looking for where the live standings are, and every tile already names its own class.</p><blockquote><p><strong>Live position</strong> — the other graph on the spectator wall — is deliberately not offered here. It refuses a class with no radio control rather than falling back to the controls on the course, so on a hall where not every class is wired you would get a wall of refusals. Live top 10 keeps reading either way.</p></blockquote><h3 id="an-analysis-wall-—-time-behind-superman-or-position-bump-which-classes" tabindex="-1">An analysis wall — Time behind Superman or Position bump: which classes <a class="header-anchor" href="#an-analysis-wall-—-time-behind-superman-or-position-bump-which-classes" aria-label="Permalink to &quot;An analysis wall — Time behind Superman or Position bump: which classes&quot;">​</a></h3><p>These two are the same screen drawing two different things, so everything below applies to both. Assign classes the same way again — the <strong>Classes</strong> column in the screen&#39;s row, or the <strong>Classes</strong> section in the screen&#39;s settings — and the grid in the settings re-shapes as you add and remove, because the wall does.</p><p>Either wall holds <strong>4 classes</strong>, laid out two across and two down. That is fewer than a Live top 10 wall on purpose: a live board can give up what it says — the club, the leg times — and still show you the runners, while this one is a plot with ten lines on it and a name beside each, and there is nothing on it to give up. Four is what stays readable on a TV. <strong>Add classes</strong> stops offering once you are at four; remove one to make room. A screen given more than four (from the table row, which has no limit, or by an older version) draws the first four in your order and its row says <strong>First 4 only</strong>.</p><p>Each tile draws the <strong>top ten</strong> of its class.</p><p><img src="'+d+'" alt="A Time behind Superman wall: four tiles. M21E draws six lines falling away from 0:00 across controls 1 to 4 and the finish, with a legend of the six runners and the gap each finished on. W21E says &quot;No board for this class&quot;; M20 and W20 say &quot;Not enough downloaded splits to build an analysis for this class yet.&quot;"></p><p>On <strong>Time behind Superman</strong>, Superman is a runner who never existed: someone who took the fastest split on every leg of the course. Their total is what the race could have been won in if all the best splits had belonged to one person. Every line shows how far behind that a runner stands at each control, so a line that drops steeply is time lost on that leg — usually while finding a control — and a line that stays flat is a leg run at the best pace in the field. Underneath, the ten are listed in finishing order with the gap each finished on. The perfect race is built from the <strong>whole class</strong>, not just the ten drawn: a runner well down the results who was fastest on one leg still counts, which is what makes the figure &quot;how fast this course could have been run&quot;.</p><p>On <strong>Position bump</strong>, each line is a runner&#39;s place overall after every leg — 1 is whoever led the class at that point. A line climbing toward the top is gaining places and one falling away is slipping back, which is the race as it would have unfolded live. It starts at the first control rather than the start line, because nobody has a place at the gun, and the legend lists the ten with their race times. Places are counted across the <strong>whole class</strong>, not across the ten lines drawn, so a tile for a class of forty shows real positions rather than 1 to 10.</p><p><img src="'+c+'" alt="The same four classes on a Position bump wall: M21E&#39;s tile draws each runner&#39;s place, 1 to 6, after every control, with lines crossing as places change, and a legend with the six race times. The other three tiles carry the same refusals as the Superman wall."></p><p>Both are <strong>finisher</strong> graphs — they are drawn from downloaded cards, so a class where nobody has come in yet says so rather than sitting blank, and fills in as the cards are read. A class neither can draw at all — a relay, a score course, a class running several courses — says that on its own tile instead, so you can see that you assigned it.</p><p>Like the Live top 10 wall they size themselves, so there is no columns or auto-scroll setting, and nothing scrolls — nor, unlike that wall, a font size. The header names the graph rather than the event.</p><h4 id="letting-the-wall-choose-cycle-through-all-classes" tabindex="-1">Letting the wall choose: Cycle through all classes <a class="header-anchor" href="#letting-the-wall-choose-cycle-through-all-classes" aria-label="Permalink to &quot;Letting the wall choose: Cycle through all classes&quot;">​</a></h4><p>Tick <strong>Cycle through all classes</strong> in the screen&#39;s settings and the wall stops reading its class list and works through the whole event by itself. It shows the first four classes, then the top two slide off the top, the bottom two slide up to take their place and the next two come in from underneath. At the end it wraps round to the first four and keeps going.</p><p><strong>Seconds</strong> — beside that tick box — sets how long each screenful is held: ten by default, and anything from five seconds to two minutes. A TV by the download desk that people walk past wants longer than one over the finish that everybody is already watching. The slide itself always takes two seconds on top of that, and is deliberately slow: it has to be possible to follow your class from the bottom half of the screen to the top.</p><p>Classes come in the event&#39;s own class order — the one you set in <strong>Classes → Sort order</strong> — and only the ones these graphs can draw are included, so relays, score courses and classes running several courses are passed over rather than given a turn on the wall to say they can&#39;t be drawn. A class nobody has downloaded from yet <strong>is</strong> included; it fills in as the cards are read.</p><p>With the setting on, the <strong>Classes</strong> section disappears from the settings, because there is nothing left to arrange, and the screen&#39;s row in the Screens table says <strong>All classes</strong> instead of counting them. Your chosen classes are not thrown away — untick the box and they are back exactly as you left them. If the event has four classes or fewer, the wall shows them all and simply sits still; there is nowhere to cycle to.</p><p><img src="'+g+'" alt="Screen settings for tv7, a Time behind Superman screen, with Cycle through all classes ticked and Seconds set to 15. There is no Classes section."></p><h3 id="a-start-times-screen-by-class-or-by-course" tabindex="-1">A Start times screen: by class or by course <a class="header-anchor" href="#a-start-times-screen-by-class-or-by-course" aria-label="Permalink to &quot;A Start times screen: by class or by course&quot;">​</a></h3><p>In the screen&#39;s settings, choose <strong>Group by</strong> — <strong>Class</strong> or <strong>Course</strong> — and then tick the classes (or courses) to show. One button at the top of that list toggles between <strong>Select all</strong> and <strong>Deselect all</strong>, depending on what&#39;s ticked.</p><p>With everything ticked, the screen stores &quot;all&quot; rather than today&#39;s list, so a class entered at nine in the morning turns up on the TV by itself. That matters because nobody is standing at the screen to re-pick it. If you tick only some, the screen shows exactly those and nothing else.</p><p>Because &quot;nothing ticked&quot; is how the screen stores &quot;everything&quot;, it can&#39;t also mean &quot;show nothing&quot; — a screen showing nothing isn&#39;t a useful thing to configure. So if you clear the list, <strong>Save</strong> and <strong>Apply</strong> are disabled until you pick something, or select all again.</p><p>Your two lists are kept separately: switch a screen from Class to Course and back, and the classes you picked are still there.</p><p><img src="'+p+'" alt="Screen settings for a Start times screen called start: Shows Start times, Group by Class, Classes reading &quot;All classes&quot;, Only classes with start times unticked, Show club ticked, Font size 14, Columns 2, Auto-scroll and Show header ticked."></p><p>Two more switches sit under that picker:</p><ul><li><strong>Only classes with start times</strong> (or <strong>Only courses…</strong>, following the Group by choice) leaves off a class nobody is starting in. Off by default, because before the draw is done that would empty the board — an empty board looks broken. Turn it on the morning of the race, when a class nobody is starting in is a column of nothing taking room from the ones that are. It works per class, not per person: a class where one runner has no time yet still shows, with that runner in it.</li><li><strong>Show club</strong> names each competitor&#39;s club beside them. On by default.</li></ul><p>A few things worth knowing about a start times screen:</p><ul><li>It shows the time each competitor is <strong>due</strong> to start, not the time they actually went. Somebody who has taken a punching start still appears at their allocated time.</li><li>Competitors marked <strong>DNS</strong>, <strong>Not competing</strong> or <strong>Cancelled</strong> are left off. Anyone with no start time yet is still listed, at the end of their group.</li><li>Relay teams appear as teams, once each — not as their individual leg runners.</li><li>Grouped by <strong>Course</strong>, each row also names the competitor&#39;s class, because one course heading covers several classes. Grouped by <strong>Class</strong>, the heading above already said it.</li><li>Times show <strong>seconds</strong> only when some start isn&#39;t on a whole minute — and then on every row, so the column doesn&#39;t step sideways as the board redraws.</li><li>If anyone&#39;s class or course can&#39;t be worked out, they get their own <strong>No class</strong> / <strong>No course</strong> group at the end rather than being dropped. Somebody left off a start list would read it as not running. (This only happens when you haven&#39;t narrowed the screen to particular classes — a screen asked for M21 isn&#39;t also asking for the undecided.)</li><li>Before anything is entered, the screen says so and points you back here.</li></ul><p>It doesn&#39;t need the event to be started, so you can prop one up first thing in the morning and it will already be showing the day&#39;s start list.</p><p><img src="'+u+'" alt="A Start times screen on a TV, headed &quot;Start times&quot;: M21E in the left column and W21E, M20 and Open in the right, each competitor on one line with their start time, name and club abbreviation."></p><h2 id="adjusting-a-screen-s-settings" tabindex="-1">Adjusting a screen&#39;s settings <a class="header-anchor" href="#adjusting-a-screen-s-settings" aria-label="Permalink to &quot;Adjusting a screen&#39;s settings&quot;">​</a></h2><p>Click the <strong>gear</strong> icon in a screen&#39;s row to open <strong>Screen settings</strong>. There are two tabs, <strong>Settings</strong> and <strong>Snapshot</strong>.</p><p><strong>Settings</strong> — the layout and content of the display. <strong>Shows</strong>, <strong>Theme</strong>, <strong>Rotation</strong>, <strong>Language</strong> and <strong>Show header</strong> apply to any screen. <strong>Font size</strong>, <strong>Columns</strong> and <strong>Auto-scroll</strong> apply to a Leaderboard and a Start times screen — the walls decide all three for themselves. The start-times settings appear only on a Start times screen, and everything else in the table below only on a Leaderboard.</p><p><strong>Changing what a screen shows</strong> can leave it carrying more classes than the new display can draw — a Leaderboard with ten classes switched to an analysis wall, which holds four. The surplus come <strong>off the screen</strong> as soon as you choose, keeping the order you arranged them in, so the class grid redraws as the four that will actually be on the TV. <strong>Cancel</strong> puts them all back if that wasn&#39;t what you meant. Switching the other way — to a display that holds more — brings back any classes the screen was carrying but not drawing.</p><p><strong>Theme</strong> is <strong>Light</strong> or <strong>Dark</strong>, and it is the screen&#39;s own — set it per screen, or set every Leaderboard TV at once with <strong>Edit all Leaderboards</strong> (that button only appears once the event has at least one <code>tv</code>-named Leaderboard screen). New screens are light. There is deliberately no &quot;follow the device&quot; option: a TV has nobody standing at it, and a board that went dark because the stick driving it decided it was evening would have changed without anyone asking.</p><p><strong>Rotation</strong> is for a TV hung on its side, in portrait. <strong>90° clockwise</strong> and <strong>90° anticlockwise</strong> turn the board the screen shows, whatever it is, and lay it out tall and narrow to match the TV. Which of the two you need depends on which way the TV went over: if the board reads upside down, choose the other one. Nothing needs changing on the TV itself or on the stick or computer driving it, which is the point — many of them can&#39;t turn their picture. Set it per screen, or for every Leaderboard TV at once with <strong>Edit all Leaderboards</strong>; new screens are not rotated.</p><p>A portrait screen is narrow, so it is worth revisiting the layout once it&#39;s turned: fewer <strong>Columns</strong> on a Leaderboard, and <strong>Stacked</strong> rather than <strong>Side by side</strong> for a Live top 10 wall.</p><p>The <strong>Snapshot</strong> tab shows a turned screen upright, the way people in the hall read it — whichever way the TV hangs. So it can&#39;t tell you a TV went over the other way: check that by looking at the TV, and if it reads upside down, choose the other rotation. The tab says so for any screen that is turned.</p><p>A screen only knows it&#39;s turned once it has read its settings, so a few things on it still appear sideways on a TV hung in portrait: the moment it is opened, while it waits to be set up, and — for as long as it lasts — the page it shows when <strong>no event is live</strong>, with its list of recent events. Once the event is live the board turns. A TV propped up first thing in the morning, before the event is started, shows that page sideways until then.</p><p>Any screen:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Shows</strong></td><td><strong><a href="./leaderboard">Leaderboard</a></strong>, <strong>Start times</strong>, <strong>Live top 10</strong>, <strong>Time behind Superman</strong> or <strong>Position bump</strong>.</td><td>Leaderboard</td></tr><tr><td><strong>Theme</strong></td><td><strong>Light</strong> or <strong>Dark</strong>. The screen&#39;s own — see above.</td><td>Light</td></tr><tr><td><strong>Rotation</strong></td><td><strong>None</strong>, <strong>90° clockwise</strong> or <strong>90° anticlockwise</strong>, for a TV hung in portrait — see above.</td><td>None</td></tr><tr><td><strong>Language</strong></td><td>Render this screen in a particular language, whatever the browser showing it is set to. <strong>Default</strong> follows the browser.</td><td>Default</td></tr><tr><td><strong>Show header (logo, event name, clock)</strong></td><td>The strip across the top. Turn off to reclaim space.</td><td>on</td></tr></tbody></table><p>A Leaderboard and a Start times screen add:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Font size</strong></td><td>Base text size, 6 to 72. Larger for a TV seen from across the arena.</td><td>10 (14 for a screen created by opening its URL)</td></tr><tr><td><strong>Columns</strong></td><td>How many columns sit side by side (1–6). More columns fit more on a wide TV.</td><td>2</td></tr><tr><td><strong>Auto-scroll</strong></td><td>Scroll long lists automatically so everyone gets airtime.</td><td>on</td></tr><tr><td><strong>Smoother scrolling (newer browsers)</strong></td><td>Shown while Auto-scroll is on. Lets the browser do the scrolling, which stays smooth while the board is busy updating. Many TVs&#39; built-in browsers can&#39;t do this; on those the screen scrolls the usual way, so it&#39;s safe to try.</td><td>off</td></tr></tbody></table><p>A Live top 10 wall adds its own <strong>Font size</strong> (<strong>Large</strong>, <strong>Medium</strong>, <strong>Small</strong> or <strong>Extra small</strong>, default Large) and <strong>Class layout</strong> (<strong>Side by side</strong> or <strong>Stacked</strong>, default Side by side) — see above. An analysis wall adds <strong>Cycle through all classes</strong> and its <strong>Seconds</strong>.</p><p>A Start times screen adds <strong>Group by</strong>, the class or course picker, <strong>Only classes with start times</strong> and <strong>Show club</strong>, all described above.</p><p><img src="'+w+'" alt="Screen settings for a Leaderboard screen: Shows, Theme, Rotation and Language across the top; the Classes grid with M21E and W21E in two columns; Font size, Columns, Name column width, Club display, Competitor time display, High-contrast text, Max places per class, Max radios, Pin top places (Top 10) and Pinned classes; then the switches. Delete at the bottom left, Cancel, Apply and Save at the right."></p><p>A Leaderboard screen adds:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Name column width</strong></td><td>Small / Medium / Large room for competitor names.</td><td>Medium</td></tr><tr><td><strong>Club display</strong></td><td><strong>Hide</strong> the club, or show <strong>Abbreviations</strong> or <strong>Full names</strong>.</td><td>from your screen defaults, else Hide</td></tr><tr><td><strong>Max radios</strong></td><td>How many radio-control splits to show per course (0–100).</td><td>4</td></tr><tr><td><strong>Competitor time display</strong></td><td><strong>Elapsed</strong> time, <strong>Difference</strong> (behind the leader), or <strong>Both</strong>.</td><td>Both</td></tr><tr><td><strong>Max places per class</strong></td><td>Show <strong>All</strong> finishers or just the <strong>Top 3</strong> to <strong>Top 10</strong>.</td><td>All</td></tr><tr><td><strong>High-contrast text</strong></td><td>Draw the text darker and slightly heavier, so it stays legible after a TV enlarges the picture. <strong>Automatic</strong> does so when the screen is drawn at 1280 × 720 or less — see <strong>Resolution</strong> below; <strong>On</strong> and <strong>Off</strong> decide for this screen whatever its resolution. Not offered for the <strong>manager</strong> screen, which is always drawn as normal.</td><td>Automatic</td></tr><tr><td><strong>Pin top places</strong></td><td>Keep each class&#39;s top 3–10 places at the top while the screen scrolls — see below.</td><td>Top 3</td></tr><tr><td><strong>Pinned classes</strong></td><td>Which classes pin their top places. Appears once <strong>Pin top places</strong> is on.</td><td>all classes</td></tr><tr><td><strong>Show club icon</strong></td><td>Show each club&#39;s badge.</td><td>on</td></tr><tr><td><strong>Show relay team members on single line</strong></td><td>Compact relay rows.</td><td>off</td></tr><tr><td><strong>Show projected times for competitors with radio punches</strong></td><td>Estimate finish times for runners seen at a radio control but not yet finished.</td><td>on</td></tr><tr><td><strong>Show start time</strong></td><td>Show each competitor&#39;s start time.</td><td>on</td></tr><tr><td><strong>Show class names in header</strong></td><td>Label each column with its class.</td><td>on</td></tr></tbody></table><p><strong>Pinning the top places.</strong> An auto-scrolling Leaderboard normally moves everything, so a class&#39;s leaders scroll off the top and the TV spends much of its time on the middle and back of the field — often runners still out, DNFs and mispunches. With <strong>Pin top places</strong> set to, say, <strong>Top 10</strong>, each pinned class keeps its header and its top ten places at the top of the screen while the rest of the class scrolls up underneath them, so anyone reading the board always sees the leaders and can compare themselves against them. The scroll itself behaves as before — down in steps, a pause at the bottom, then back to the top — it just steps shorter when the pinned rows leave less room, so nobody is skipped.</p><p><strong>Pinned classes</strong> starts at every class on the screen. Narrow it when only some classes should pin: two big classes such as M21 and W21 side by side on a screen of their own are the typical case. Pinned rows take room from the rows that scroll, so a screen of many classes that all pin can leave little or no room to scroll through — pin fewer classes or fewer places, or use more columns. What is pinned is the top of the class as the board shows it: a runner still out who is projected to finish in the top ten sits in those rows with the finishers, and is pinned with them. Runners out with nothing to project from are never pinned, and until anyone in a class has finished there is nothing to pin, so that class scrolls as normal. A relay class pins its top teams the same way.</p><p><img src="'+m+'" alt="A Leaderboard screen part-way through a scroll: on the left, M21 Elite&#39;s header and its top five finishers stay at the top while the runners still on course have scrolled up underneath them; on the right, M21E is not pinned and has scrolled as a whole."></p><p><strong>Snapshot</strong> — on the <strong>Snapshot</strong> tab, click <strong>Refresh snapshot</strong> to capture a live screenshot of the screen as it currently renders. It&#39;s the quickest way to check the layout looks right without walking over to the TV. (A snapshot only works while the screen is open somewhere.)</p><p><img src="'+f+'" alt="The Snapshot tab of tv12&#39;s settings, with Refresh snapshot at the top right, the note &quot;Shown upright, the way people in the hall read it. If the TV itself reads upside down, choose the other rotation.&quot; and &quot;No snapshot available&quot; until it is refreshed."></p><p>Use <strong>Apply</strong> to save and keep tweaking, or <strong>Save</strong> to save and close.</p><h2 id="keeping-an-eye-on-a-running-screen" tabindex="-1">Keeping an eye on a running screen <a class="header-anchor" href="#keeping-an-eye-on-a-running-screen" aria-label="Permalink to &quot;Keeping an eye on a running screen&quot;">​</a></h2><p>Once a screen is open on a display, its row reports live health so you can spot a TV that&#39;s dropped off. <strong>FPS</strong>, <strong>Resolution</strong>, the load and device columns, <strong>DC</strong> and <strong>RL</strong> are hidden until you turn them on in the columns menu at the right-hand end of the header row; <strong>Screen ID</strong> and <strong>Settings</strong> are always shown.</p><ul><li><strong>Last heard from</strong> — when the screen last checked in, and how long ago. A screen that has never been opened says <strong>Never</strong>. Green means it&#39;s reporting now; grey means it&#39;s gone quiet.</li><li><strong>FPS</strong> — how smoothly it&#39;s refreshing (green is healthy, orange is marginal, red is struggling). Click the number for a history graph that also marks disconnects, reconnects and reloads.</li><li><strong>Resolution</strong> — the resolution the screen is really drawn at, in pixels. Hover over it to see the size the browser lays the page out at and how many screen pixels it uses for each one. If it&#39;s lower than the TV&#39;s own resolution — 3840 × 2160 on a 4K set — the TV is enlarging the picture, and the board will look softer than the TV&#39;s own menus. A smart TV&#39;s built-in browser is often the cause; a laptop or media stick sending the TV its full resolution draws it sharply. The cell is blank until the screen next checks in. A Leaderboard drawn at 1280 × 720 or less switches on its own to darker, slightly heavier text, which stays legible better after the TV enlarges it — unless its <strong>High-contrast text</strong> setting says <strong>On</strong> or <strong>Off</strong>.</li><li><strong>Load time</strong> — how long the screen spent loading, from opening the page until the last of its data arrived. Time spent with no event to show isn&#39;t counted. Hover over it to see each step, how many records it brought and how long it took, and any <strong>Waiting for an event</strong> time. It says <strong>Loading</strong> while a screen is still getting ready, and names a step that failed, so you can tell a slow TV from a stuck one without walking over to it.</li><li><strong>App load</strong> — how long the application itself took to download and start. On a TV this is usually the longest step.</li><li><strong>Screen resolution</strong>, <strong>Pixel ratio</strong>, <strong>Page size</strong>, <strong>Browser engine</strong>, <strong>Browser</strong> and <strong>User agent</strong> — what the TV told meshO about itself, the same details it shows while it loads. Compare them when a board is slow or small on one TV and fine on the next. A TV&#39;s browser often reports less than the TV can show, so a 4K TV can list 1920 × 1080 here.</li><li><strong>DC / RL</strong> — counts of <strong>disconnections</strong> and <strong>force reloads</strong>, shown once there are any.</li></ul><p><img src="'+y+'" alt="FPS history for tv2: a green line near 60 frames a second that drops to about 20, with a red dashed line where it disconnected, a blue one where it reconnected, recovery to about 40, and an orange dashed line where it was reloaded. A legend underneath names FPS, Disconnected, Reconnected and Reloaded."></p><p>The <strong>refresh</strong> button at the end of the row (<strong>Force reload TV screen</strong>) reloads that display remotely — the quickest fix for a TV whose browser has got stuck. The <strong>manager</strong> row has none.</p><h2 id="deleting-a-screen" tabindex="-1">Deleting a screen <a class="header-anchor" href="#deleting-a-screen" aria-label="Permalink to &quot;Deleting a screen&quot;">​</a></h2><p>Open the screen&#39;s settings (gear icon) and click <strong>Delete</strong>, then confirm. The built-in <strong>manager</strong> screen has no <strong>Delete</strong> button. If you delete <strong>all</strong>, it is created again, with its default settings, the next time the event is opened.</p><blockquote><p><strong>Note:</strong> A display still open on a deleted screen creates it again the next time it checks in — with default settings and no classes. Close or repoint the browser on that TV before deleting its screen.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./tv-screens">TV screens</a> — set up and drive a whole bank of arena TVs at once</li><li><a href="./commentary">Commentary</a> — the announcer&#39;s live feed</li><li><a href="./leaderboard">Leaderboard</a> — the results board these screens show by default</li><li><a href="./info-screens">Info screens</a> — start clock, starters, radio-control feed and cameras, set up on the device</li><li><a href="./spectator-site-and-kiosk">Spectator site and kiosk</a> — the public pages that need no setup</li><li><a href="./../event-setup/results-quarantine">Results quarantine</a> — holding elite results back from every screen</li><li><a href="./../after-the-event/results">Results</a> — the operator-facing results and exports</li><li><a href="./../running-the-event/two-events-at-once">Running two events at once</a> — pointing each screen at its own event</li></ul>',105)])])}const x=t(b,[["render",v]]);export{q as __pageData,x as default};
